CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','secretary','accountant')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), auth_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE auth_sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE auth_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,summary TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE subjects(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
INSERT INTO subjects(name) VALUES ('پیانو'),('ویولن'),('گیتار'),('سلفژ'),('کنترپوان'),('پیانو ایرانی'),('آکاردئون');
CREATE TABLE guardians(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL);
CREATE TABLE students(id INTEGER PRIMARY KEY,code TEXT UNIQUE,first_name TEXT NOT NULL,last_name TEXT NOT NULL,english_first TEXT NOT NULL DEFAULT '',english_last TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',timezone TEXT NOT NULL DEFAULT 'Asia/Tehran',country TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','archived')),history TEXT NOT NULL DEFAULT 'unknown' CHECK(history IN ('new','old','unknown')),first_registered TEXT,missing_contact_reason TEXT NOT NULL DEFAULT '',search_text TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE student_guardians(student_id INTEGER NOT NULL REFERENCES students(id),guardian_id INTEGER NOT NULL REFERENCES guardians(id),relationship TEXT NOT NULL,PRIMARY KEY(student_id,guardian_id));
CREATE TABLE enrollments(id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id),subject_id INTEGER NOT NULL REFERENCES subjects(id),UNIQUE(student_id,subject_id));
CREATE TABLE class_offerings(id INTEGER PRIMARY KEY,subject_id INTEGER NOT NULL REFERENCES subjects(id),structure TEXT NOT NULL DEFAULT 'private' CHECK(structure IN ('private','group')),teacher TEXT NOT NULL DEFAULT 'شهرام محذوف',mode TEXT NOT NULL CHECK(mode IN ('onsite','online')),location TEXT NOT NULL DEFAULT '',course_format TEXT NOT NULL DEFAULT 'normal' CHECK(course_format IN ('normal','masterclass')));
CREATE TABLE terms(id INTEGER PRIMARY KEY,offering_id INTEGER NOT NULL REFERENCES class_offerings(id),registered_on TEXT NOT NULL,start_date TEXT,end_date TEXT,duration_minutes INTEGER CHECK(duration_minutes>0),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE student_terms(id INTEGER PRIMARY KEY,term_id INTEGER NOT NULL REFERENCES terms(id),enrollment_id INTEGER NOT NULL REFERENCES enrollments(id),number INTEGER NOT NULL CHECK(number>0),quota INTEGER NOT NULL CHECK(quota>0),status TEXT NOT NULL DEFAULT 'current' CHECK(status IN ('current','completed','paused','cancelled','planned')),renewed_from INTEGER UNIQUE REFERENCES student_terms(id),UNIQUE(enrollment_id,number),UNIQUE(term_id,enrollment_id));
CREATE TABLE invoices(id INTEGER PRIMARY KEY,student_term_id INTEGER NOT NULL UNIQUE REFERENCES student_terms(id),student_id INTEGER NOT NULL REFERENCES students(id),currency TEXT NOT NULL CHECK(currency IN ('TOMAN','USD')),base_minor INTEGER NOT NULL CHECK(base_minor>=0),discount_minor INTEGER NOT NULL DEFAULT 0 CHECK(discount_minor>=0 AND discount_minor<=base_minor),reason TEXT NOT NULL DEFAULT '',due_date TEXT,UNIQUE(id,student_id,currency));
CREATE TABLE bank_accounts(id INTEGER PRIMARY KEY,title TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('TOMAN','USD')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE payments(id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id),currency TEXT NOT NULL CHECK(currency IN ('TOMAN','USD')),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),received_on TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN ('cash','bank','other')),bank_account_id INTEGER REFERENCES bank_accounts(id),reference TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','voided')),actor_id INTEGER NOT NULL REFERENCES users(id),idempotency_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,UNIQUE(id,student_id,currency));
CREATE TABLE payment_allocations(id INTEGER PRIMARY KEY,payment_id INTEGER NOT NULL,invoice_id INTEGER NOT NULL,student_id INTEGER NOT NULL,currency TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),FOREIGN KEY(payment_id,student_id,currency) REFERENCES payments(id,student_id,currency),FOREIGN KEY(invoice_id,student_id,currency) REFERENCES invoices(id,student_id,currency),UNIQUE(payment_id,invoice_id));
CREATE TRIGGER allocation_guard BEFORE INSERT ON payment_allocations BEGIN
SELECT CASE WHEN NEW.amount_minor > COALESCE((SELECT amount_minor FROM payments WHERE id=NEW.payment_id AND status='confirmed'),0)-COALESCE((SELECT SUM(amount_minor) FROM payment_allocations WHERE payment_id=NEW.payment_id),0) THEN RAISE(ABORT,'payment overallocation') END;
SELECT CASE WHEN NEW.amount_minor > (SELECT base_minor-discount_minor FROM invoices WHERE id=NEW.invoice_id)-COALESCE((SELECT SUM(a.amount_minor) FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE a.invoice_id=NEW.invoice_id AND p.status='confirmed'),0) THEN RAISE(ABORT,'invoice overallocation') END;
END;
CREATE TABLE sessions(id INTEGER PRIMARY KEY,idempotency_key TEXT UNIQUE,request_hash TEXT,term_id INTEGER NOT NULL REFERENCES terms(id),starts_at TEXT NOT NULL,timezone TEXT NOT NULL,duration_minutes INTEGER CHECK(duration_minutes>0),replacement_for INTEGER UNIQUE REFERENCES sessions(id));
CREATE TABLE attendance(id INTEGER PRIMARY KEY,session_id INTEGER NOT NULL REFERENCES sessions(id),student_term_id INTEGER NOT NULL REFERENCES student_terms(id),status TEXT NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','present','absent','cancelled')),counts INTEGER NOT NULL DEFAULT 0 CHECK(counts IN (0,1)),reason TEXT NOT NULL DEFAULT '',cancelled_by TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,CHECK((status='present' AND counts=1) OR (status IN ('reserved','cancelled') AND counts=0) OR (status='absent' AND length(trim(reason))>0)),CHECK(status!='cancelled' OR (length(trim(reason))>0 AND cancelled_by IN ('teacher','student','academy','other'))),UNIQUE(session_id,student_term_id));
CREATE TRIGGER attendance_term_guard BEFORE INSERT ON attendance BEGIN SELECT CASE WHEN (SELECT term_id FROM sessions WHERE id=NEW.session_id)!=(SELECT term_id FROM student_terms WHERE id=NEW.student_term_id) THEN RAISE(ABORT,'inconsistent session term') END; END;
CREATE INDEX student_search_idx ON students(status,id);
CREATE INDEX attendance_membership_idx ON attendance(student_term_id,status);
CREATE INDEX session_start_idx ON sessions(starts_at);
